import{_ as n,l,o as e,c as s,v as r,p as i,x as o,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"贸易与增长","description":"","frontmatter":{"title":"贸易与增长","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/trade-growth.md","filePath":"econ/trade-growth.md","lastUpdated":1789023840000}'),m={name:"econ/trade-growth.md"};function h(B,a,c,u,_,A){const t=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="贸易与增长" tabindex="-1">贸易与增长 <a class="header-anchor" href="#贸易与增长" aria-label="Permalink to &quot;贸易与增长&quot;">​</a></h1><div class="epigraph"><p>静态比较利益是一次水平效应；增长问的是贸易是否改变创新与资本积累的斜率。工具若只推动收入水平，不能把回归里的开放系数读成增长率。</p><footer>—— Frankel and Romer, Does Trade Cause Growth?, AER 1999；Grossman and Helpman, Innovation and Growth in the Global Economy</footer></div><p><a href="/econ/offshoring-tasks">上一课</a>把贸易收到任务。贸易理论课序在此收束长期。下一单元国际金融续从 Lucas 悖论起：资本为何不按教科书流向穷国。本课钉贸易与增长的水平 / 增长效应，以及识别。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态李嘉图 / Krugman / Melitz 给出开放后的<strong>水平</strong>（实际收入一次跳升）。内生增长：贸易扩大市场（创新租金）、扩散技术、或通过竞争消灭模仿——斜率可以变。Frankel–Romer：用地理构造的贸易预测值当 IV，估贸易份额对收入水平的效应，发现正且大于 OLS。缺口是：那是水平（或长期水平），不是每年增长率；地理工具排除「收入高所以贸易多」的反向，不排除地理还通过制度、疾病进收入（后续批评）。Rodriguez–Rodrik：开放指标与政策内生，简单跨国回归不可信。</p><p><span class="marginnote">Grossman–Helpman：开放对创新的符号取决于知识溢出是国际的还是国内的、以及竞争是偷走租金还是扩大市场。理论不定，要机制而不是一条 \\(\\beta\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>水平 vs 增长：在 AK / 半内生增长里，开放可以只抬水平（资本向新稳态过渡时表现为暂时高增长）。实证要声明因变量是 \\(\\ln y\\) 还是 \\(\\Delta\\ln y\\)。IV：地理（FR）、政策突变、关税时间表；每一个都有排除故事。Melitz 动态（Atkeson–Burstein、Sampson）把选择与创新连起来：贸易改变创新激励，斜率可以动。本课不估新的 \\(\\beta\\)。</p>',8)),(e(),i(p,null,{default:o(()=>[d(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAT%5B%22%E9%9D%99%E6%80%81%E8%B4%B8%E6%98%93%22%5D%20--%3E%20LEV%5B%22%E6%B0%B4%E5%B9%B3%3A%20%E5%AE%9E%E9%99%85%E6%94%B6%E5%85%A5%E8%B7%B3%E5%8D%87%22%5D%0A%20%20INN%5B%22%E5%88%9B%E6%96%B0%20%2F%20%E6%89%A9%E6%95%A3%22%5D%20--%3E%20SLOPE%5B%22%E5%8F%AF%E8%83%BD%E6%94%B9%E5%A2%9E%E9%95%BF%E7%8E%87%22%5D%0A%20%20FR%5B%22%E5%9C%B0%E7%90%86%20IV%22%5D%20--%3E%20Y%5B%22%E5%AF%B9%E6%94%B6%E5%85%A5%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20GEO%5B%22%E5%9C%B0%E7%90%86%E4%B9%9F%E8%BF%9B%E5%88%B6%E5%BA%A6%22%5D%20--%3E%20EX%5B%22%E6%8E%92%E9%99%A4%E4%B8%8D%E5%B9%B2%E5%87%80%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与计量课程：这是 IV 在宏观跨国，弱工具与排除的课都适用。不要用 DML 替代地理故事。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制候选三条。市场扩大：出口提高创新租金（Krugman / 内生增长）。知识扩散：进口品种与 FDI 带技术（Coe–Helpman 溢出）。竞争：减少惰性或偷走租金（Schumpeter 两刃）。资本积累：开放改实际利率与 \\(K\\) 路径，仍可能只是水平。穷国若制度差，开放可以把资源配置到寻租而不是创新——增长效应可以负。</p><p>与 China shock：局部劳动市场损失是过渡与摩擦；增长文献问几十年的 \\(y\\)。两套时间尺度，不要用 CZ 十年就业否证 Frankel–Romer 的水平效应，也不要用跨国 \\(\\beta\\) 否认 ADH。</p><p><span class="marginnote">贸易课序到此：比较成本、禀赋与分配、IRS 与品种、异质企业、引力与 EK、关税与协定、价值链、中国冲击、任务、增长。下一单元资本流动之谜，货物理论当背景不再重推。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不宣称「开放一定加快增长」。不重写<a href="/econ/solow-1956-paper">索洛</a>附录。国际金融续的 Lucas 悖论问的是资本为何不流向穷国，与本课「贸易是否提高 \\(A\\)」相关但对象是 \\(K\\) 的跨境，不是货物。不要把 FTA 虚拟变量的增长回归当成 Bagwell–Staiger 的福利。</p><p>后课默认：静态贸易给水平；增长效应要创新 / 积累机制，理论符号不定。Frankel–Romer 是水平 IV，排除有争议。局部冲击证据与长期跨国证据分层。下一课 Lucas 悖论：资本不按边际产出流向穷国。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>静态比较利益主要是水平效应；增长要斜率机制。</li><li>Frankel–Romer 地理 IV 对准收入水平，排除不完美。</li><li>Grossman–Helpman：市场、溢出、竞争三通道，符号不定。</li><li>局部劳动市场损失不自动否证长期水平增益。</li><li>出处：Frankel and Romer, <em>AER</em> 1999；Grossman and Helpman；Rodriguez and Rodrik。</li></ul>',10))])}const D=n(m,[["render",h]]);export{k as __pageData,D as default};
